-- NexTech: estructura MySQL 8 / MariaDB 10.6+
-- El instalador importa catalog.json y crea la cuenta de administrador.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', phone VARCHAR(30) NOT NULL DEFAULT '', auth_version INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (slug VARCHAR(40) PRIMARY KEY, name VARCHAR(90) NOT NULL, icon VARCHAR(30) NOT NULL, position INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTO_INCREMENT, sku VARCHAR(80) NOT NULL UNIQUE, category VARCHAR(40) NOT NULL, name VARCHAR(220) NOT NULL, brand VARCHAR(90) NOT NULL, description TEXT NOT NULL, specs TEXT NOT NULL, image VARCHAR(1500) NOT NULL DEFAULT '', source_url VARCHAR(1500) NOT NULL DEFAULT '', source_checked VARCHAR(20) NOT NULL DEFAULT '', price INTEGER NOT NULL DEFAULT 0, compare_price INTEGER NOT NULL DEFAULT 0, stock INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, verified INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS cart (user_id INTEGER NOT NULL, product_id INTEGER NOT NULL, qty INTEGER NOT NULL, PRIMARY KEY(user_id,product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, product_id INTEGER NOT NULL, PRIMARY KEY(user_id,product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS addresses (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, label VARCHAR(50) NOT NULL, recipient VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, street VARCHAR(250) NOT NULL, colony VARCHAR(120) NOT NULL, city VARCHAR(120) NOT NULL, state VARCHAR(120) NOT NULL, postal_code VARCHAR(10) NOT NULL, notes VARCHAR(500) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS orders (id VARCHAR(40) PRIMARY KEY, user_id INTEGER NOT NULL, status VARCHAR(30) NOT NULL, payment_status VARCHAR(30) NOT NULL, provider VARCHAR(30) NOT NULL, payment_id VARCHAR(190) UNIQUE, checkout_url TEXT, subtotal INTEGER NOT NULL, shipping INTEGER NOT NULL, total INTEGER NOT NULL, address TEXT NOT NULL, idempotency_key VARCHAR(100) NOT NULL UNIQUE, tracking VARCHAR(200) NOT NULL DEFAULT '', notes TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(40) NOT NULL, product_id INTEGER NOT NULL, sku VARCHAR(80) NOT NULL, name VARCHAR(220) NOT NULL, price INTEGER NOT NULL, qty INTEGER NOT NULL, image VARCHAR(1500) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_events (id INTEGER PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(40) NOT NULL, message VARCHAR(500) NOT NULL, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS reset_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, action VARCHAR(100) NOT NULL, detail TEXT NOT NULL, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS payment_events (event_id VARCHAR(190) PRIMARY KEY, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX idx_products_category ON products(category,active);

CREATE INDEX idx_orders_user ON orders(user_id,created_at);

CREATE INDEX idx_items_order ON order_items(order_id);

CREATE INDEX idx_addresses_user ON addresses(user_id);

CREATE INDEX idx_events_order ON order_events(order_id);

CREATE INDEX idx_resets_user ON reset_tokens(user_id);

